void DistributedDeploymentWindow::RequestClose(){if(!fBusy){QDialog::reject();return;}fCloseAfterWait=true;if(fCanceled)fCanceled->store(true);fWaitStatus->setText(tr("Stopping local waiting before closing. Backend work and audit records are retained."));fStopWaiting->setEnabled(false);}
void DistributedDeploymentWindow::reject(){RequestClose();}
Logger DistributedDeploymentWindow::Logger(){const QPointer<DistributedDeploymentWindow> guard(this);return [guard](const QString &text){if(guard)QMetaObject::invokeMethod(guard,[guard,text]{if(guard){guard->fLog->appendPlainText(text);guard->fWaitStage=text.left(240);}},Qt::QueuedConnection);};}
void DistributedDeploymentWindow::Async(std::function<QJsonObject()> task,std::function<void(QJsonObject)> done){
    if(fBusy)return;
    fBusy=true;fCloseAfterWait=false;fCanceled=std::make_shared<std::atomic_bool>(false);fWaitClock.start();fWaitStage=tr("Checking services at %1:%2").arg(fAddress->text()).arg(fPort->value());fWaitStatus->setText(fWaitStage);fStopWaiting->setEnabled(true);fControls->setEnabled(false);
    const auto canceled=fCanceled;auto *watcher=new QFutureWatcher<QPair<QJsonObject,QString>>(this);
    connect(watcher,&QFutureWatcher<QPair<QJsonObject,QString>>::finished,this,[this,watcher,done]{const auto result=watcher->result();watcher->deleteLater();fBusy=false;fStopWaiting->setEnabled(false);fControls->setEnabled(true);if(!result.second.isEmpty()){fLog->appendPlainText(tr("Operation incomplete: %1").arg(result.second));fWaitStatus->setText(result.second);}else{try{done(result.first);fWaitStatus->setText(tr("Operation finished. Check the result below."));}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));fWaitStatus->setText(QString::fromUtf8(error.what()));}}if(fCloseAfterWait)QDialog::reject();});
    watcher->setFuture(QtConcurrent::run([task,canceled]{OperationScope scope(canceled);try{return qMakePair(task(),QString());}catch(const std::exception &error){return qMakePair(QJsonObject(),QString::fromUtf8(error.what()));}}));
}

void DistributedDeploymentWindow::OpenProject(const QString &selectedDirectory){if(fBusy)return;try{QString directory=selectedDirectory;if(QFile::exists(directory+"/relocated-to.json"))directory=Parse(Read(directory+"/relocated-to.json"))["directory"].toString();auto project=Parse(Read(directory+"/project.json",64*1024*1024));auto pairedNodes=project["nodes"].toArray();for(const auto &name:QDir(directory+"/paired-nodes").entryList({"*.json"},QDir::Files)){const auto node=Parse(Read(directory+"/paired-nodes/"+name));bool present=false;for(const auto &entry:pairedNodes)present=present || entry.toObject()["id"]==node["id"];if(!present)pairedNodes.append(node);}project["nodes"]=pairedNodes;Require(project["schema"].toInt()==1 && project["kind"]=="getdaq.distributed-project","Unsupported project file");QMap<QString,QByteArray> loaded;for(const auto &value:project["content_files"].toArray()){const auto entry=value.toObject();const auto sha=Digest(entry["sha256"].toString());const auto bytes=entry.contains("base64")?QByteArray::fromBase64(entry["base64"].toString().toLatin1()):Read(directory+"/content/"+sha,16*1024*1024);Require(Sha(bytes)==sha,"Saved project source differs");loaded[Id(entry["id"].toString())]=bytes;}for(const auto &value:project["nodes"].toArray()){const auto node=value.toObject();Require(node["credential_file"].toString()==directory+"/nodes/"+Id(node["id"].toString())+".token","Imported node credential must belong to this private project directory");}fFiles=loaded;fProject=project;
QString localFolder=project["local_project_directory"].toString();
if(localFolder.isEmpty()){QSet<QString> configuredFolders;for(const auto &value:project["nodes"].toArray()){const auto node=value.toObject();if(!IsLocalHost(node))continue;if(!node["project_data_directory"].toString().isEmpty())configuredFolders.insert(node["project_data_directory"].toString());for(const auto &entry:project["groups"].toArray()){const auto folder=entry.toObject()["project_directories"].toObject()[node["id"].toString()].toString();if(!folder.isEmpty())configuredFolders.insert(folder);}}if(configuredFolders.size()==1)localFolder=*configuredFolders.begin();}
if(!localFolder.isEmpty()){fLocalDataRoot->setText(localFolder);auto nodes=fProject["nodes"].toArray();for(int i=0;i<nodes.size();++i){auto node=nodes[i].toObject();if(IsLocalHost(node)){node["project_data_directory"]=localFolder;nodes[i]=node;}}fProject["nodes"]=nodes;}
const bool currentProject=QFileInfo(fBase.deploymentProject).absoluteFilePath()==QFileInfo(directory+"/project.json").absoluteFilePath();fSource->setText(currentProject?fBase.configDir:project["configuration_source"].toString(fBase.configDir));fSync->setChecked(currentProject?fBase.syncConfiguration:project["sync_configuration"].toBool(fBase.syncConfiguration));fRoot->setText(directory);fRoot->setReadOnly(true);fMaster=QJsonObject();if(QFile::exists(directory+"/master.json")){fMaster=Parse(Read(directory+"/master.json"));fAddress->setText(fMaster["address"].toString());fPort->setValue(fMaster["port"].toInt());}fPreparation=QFile::exists(directory+"/prepared-release.json")?Parse(Read(directory+"/prepared-release.json",64*1024*1024)):QJsonObject();fActivation=QFile::exists(directory+"/active-release.json")?Parse(Read(directory+"/active-release.json",64*1024*1024)):QJsonObject();QSettings().setValue(StartupConfigurationKey()+"/distributed-project",directory);RefreshTables();const auto pending=QDir(directory+"/pending-pairings").entryList({"*.json"},QDir::Files);if(!pending.isEmpty()){fInvitation->setText("getdaq-pair:"+QString::fromLatin1(Read(directory+"/pending-pairings/"+pending[0]).toBase64(QByteArray::Base64UrlEncoding|QByteArray::OmitTrailingEquals)));fLog->appendPlainText(tr("An earlier pairing is unresolved. Its original code has been restored; use Add slave to recover its result."));}fLog->appendPlainText(tr("Project loaded. Saved records do not prove remote services are online; refresh to check."));const auto legacy=QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation)+"/projects/";if(directory.startsWith(legacy)){const auto destination=DefaultWorkspaceDirectory()+"/projects/"+QFileInfo(directory).fileName();QTimer::singleShot(0,this,[this,directory,destination]{if(!fBusy && fRoot->text()==directory)MoveProjectDirectory(destination);});}}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::ChooseProjectDirectory(){
 if(fBusy)return;const auto directory=QFileDialog::getExistingDirectory(this,tr("Choose master project directory"),DefaultWorkspaceDirectory());if(directory.isEmpty() || directory==fRoot->text())return;
 if(QFile::exists(directory+"/project.json")){OpenProject(directory);return;}
 if(!QFile::exists(fRoot->text()+"/project.json")){fRoot->setText(directory);return;}
 try{SaveProject();}catch(const std::exception &e){fLog->appendPlainText(QString::fromUtf8(e.what()));return;}
 MoveProjectDirectory(directory);
}
void DistributedDeploymentWindow::MoveProjectDirectory(const QString &directory){
 const auto previous=fRoot->text(),programs=QCoreApplication::applicationDirPath();
 Async([=]{return RelocateMasterProject(previous,directory,programs);},[this,previous](QJsonObject result){
  const auto directory=result["directory"].toString(),previousFile=fBase.filePath;auto relocate=[&](QString &path){if(path==previous || path.startsWith(previous+'/'))path=directory+path.mid(previous.size());};relocate(fBase.deploymentProject);relocate(fBase.filePath);relocate(fBase.configurationSnapshot);relocate(fBase.configDir);relocate(fBase.outputDir);
  if(!fBase.filePath.isEmpty() && QFile::exists(fBase.filePath)){RunConfig saved;QString error;if(saved.Load(fBase.filePath,&error)){saved.deploymentProject=fBase.deploymentProject;if(!saved.Save(saved.filePath,&error))fLog->appendPlainText(error);}else fLog->appendPlainText(error);}
  if(!previousFile.isEmpty() && QSettings().value(StartupConfigurationKey()).toString()==previousFile)QSettings().setValue(StartupConfigurationKey(),fBase.filePath);
  OpenProject(directory);fLog->appendPlainText(tr("Project moved to %1. Pairing identity is retained; ECC and receiver services were not stopped. The old directory is retained as history and is no longer the active project.").arg(directory));
 });
}
void DistributedDeploymentWindow::SaveProject(){fProject["configuration_source"]=fSource->text().trimmed();fProject["sync_configuration"]=fSync->isChecked();QJsonArray refreshed;for(const auto &v:fProject["groups"].toArray()){auto group=v.toObject();if(group["backend"]=="original-soap"){if(group["project_mode"].toBool()){group["master_repository"]=QFileInfo(fSource->text().trimmed()).absoluteFilePath();group["sync_configuration"]=fSync->isChecked();}group["repository_files"]=OriginalRepository(group["master_repository"].toString(),group["id"].toString(),&fFiles);ValidateOriginalFiles(group,fFiles);}refreshed.append(group);}fProject["groups"]=refreshed;PrivateDirectory(fRoot->text());auto nodes=fProject["nodes"].toArray();for(int row=0;row<fHosts->rowCount() && row<nodes.size();++row){auto node=nodes[row].toObject();if(auto *item=fHosts->item(row,0))node["name"]=item->text();nodes[row]=node;}fProject["nodes"]=nodes;QJsonArray entries;for(auto it=fFiles.begin();it!=fFiles.end();++it){const auto sha=Sha(it.value());Write(fRoot->text()+"/content/"+sha,it.value(),true);entries.append(QJsonObject{{"id",it.key()},{"sha256",sha},{"bytes",it.value().size()}});}fProject["content_files"]=entries;Write(fRoot->text()+"/project.json",Json(fProject));QSettings().setValue(StartupConfigurationKey()+"/distributed-project",fRoot->text());}
void DistributedDeploymentWindow::RefreshTables(){const auto priorSelection=SelectedGroups();const QSignalBlocker tableBlocker(fGroups);const auto previousGroup=SelectedGroup();const QSignalBlocker blocker(fDailyGroups);fDailyGroups->clear();const auto nodes=fProject["nodes"].toArray();fHosts->setRowCount(nodes.size());for(int row=0;row<nodes.size();++row){const auto node=nodes[row].toObject(),inventory=node["inventory"].toObject();const QStringList values={node["name"].toString(),node["url"].toString(),node["id"].toString(),ProjectFolder(node),node["observation"].toString(tr("Paired, not observed"))};for(int column=0;column<values.size();++column){auto *item=new QTableWidgetItem(values[column]);if(column)item->setFlags(item->flags()&~Qt::ItemIsEditable);fHosts->setItem(row,column,item);}}const auto groups=fProject["groups"].toArray();fGroups->setRowCount(groups.size());for(int row=0;row<groups.size();++row){const auto group=groups[row].toObject(),ecc=group["ecc"].toObject();fDailyGroups->addItem(group["name"].toString(group["id"].toString()),group["id"].toString());QStringList dataHosts;for(const auto &value:group["receivers"].toArray()){const auto receiver=value.toObject();try{dataHosts<<NodeById(nodes,receiver["node_id"].toString())["name"].toString();}catch(...){dataHosts<<receiver["node_id"].toString();}}QString eccHost=ecc["node_id"].toString();try{eccHost=NodeById(nodes,eccHost)["name"].toString();}catch(...){}QString state=tr("Configuration draft");if(fPreparation["phase"]=="prepared")state=tr("Prepared; check runtime version");if(fActivation["phase"]=="active" && fActivation["release_id"]==fPreparation["release_id"])state=tr("Previously activated; refresh to check");for(const auto &nodeValue:nodes)for(const auto &instanceValue:nodeValue.toObject()["inventory"].toObject()["instances"].toArray()){const auto instance=instanceValue.toObject();if(instance["group_id"]==group["id"] && instance["role"]=="ecc" && instance.contains("actual_state"))state=tr("Last observed: %1 (runtime release %2)").arg(instance["actual_state"].toString(),instance["release_id"].toString().left(12));}const QStringList values={group["name"].toString(group["id"].toString()),eccHost+':'+QString::number(ecc["port"].toInt()),dataHosts.join(", "),QString::number(group["backend"]=="original-soap"?1:group["senders"].toArray().size()),state};for(int column=0;column<values.size();++column){auto *item=new QTableWidgetItem(values[column]);item->setFlags(item->flags()&~Qt::ItemIsEditable);item->setData(Qt::UserRole,group["id"].toString());fGroups->setItem(row,column,item);}}int selected=fDailyGroups->findData(previousGroup);if(selected<0 && fDailyGroups->count())selected=0;fDailyGroups->setCurrentIndex(selected);if(selected>=0)fGroups->setCurrentCell(selected,0);if(!priorSelection.isEmpty()){fGroups->clearSelection();for(int row=0;row<fGroups->rowCount();++row)if(priorSelection.contains(fGroups->item(row,0)->data(Qt::UserRole).toString()))fGroups->selectionModel()->select(fGroups->model()->index(row,0),QItemSelectionModel::Select|QItemSelectionModel::Rows);}UpdatePathSummary();}
void DistributedDeploymentWindow::StartMaster(){try{SaveProject();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));return;}const auto root=fRoot->text(),programs=QCoreApplication::applicationDirPath(),address=fAddress->text();const int port=fPort->value();Async([=]{return EnsureMaster(root,programs,address,port);},[this](QJsonObject result){fMaster=result;fRoot->setReadOnly(true);fAddress->setReadOnly(true);fPort->setEnabled(false);SaveProject();fLog->appendPlainText(tr("Master HTTPS configuration service ready. Add an execution host or use this computer."));});}
void DistributedDeploymentWindow::PairHost(){try{SaveProject();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));return;}const auto invitation=fInvitation->text();if(invitation.trimmed().isEmpty()){fLog->appendPlainText(tr("Enable the slave and copy its one-time pairing code first."));return;}const auto root=fRoot->text(),programs=QCoreApplication::applicationDirPath(),address=fAddress->text();const int port=fPort->value();const bool accepted=fConfigurationWarningAccepted;const auto log=Logger();Async([=]{log("Starting / checking master configuration service…");const auto master=EnsureMaster(root,programs,address,port);log("Connecting to the slave and checking its pairing identity…");return QJsonObject{{"master",master},{"node",PairNode(master,invitation)}};},[this](QJsonObject result){fMaster=result["master"].toObject();auto nodes=fProject["nodes"].toArray();const auto node=result["node"].toObject();bool found=false;for(int i=0;i<nodes.size();++i)if(nodes[i].toObject()["id"]==node["id"]){auto updated=node;updated["name"]=nodes[i].toObject()["name"];if(nodes[i].toObject().contains("root"))updated["root"]=nodes[i].toObject()["root"];nodes[i]=updated;found=true;}if(!found)nodes.append(node);fProject["nodes"]=nodes;fInvitation->clear();SaveProject();RefreshTables();fLog->appendPlainText(tr("Host paired and identity verified. You can now add an ECC / board group."));});}
void DistributedDeploymentWindow::ApplyLocalProjectFolder(){
    if(fBusy)return;
    const auto folder=QDir::cleanPath(fLocalDataRoot->text().trimmed());
    if(!QDir::isAbsolutePath(folder)){fLog->appendPlainText(tr("Use an absolute local project folder."));return;}
    if(folder==fProject["local_project_directory"].toString())return;
    const auto before=fProject;
    try{
        fProject["local_project_directory"]=folder;
        auto nodes=fProject["nodes"].toArray();QSet<QString> localIds;
        for(int i=0;i<nodes.size();++i){auto node=nodes[i].toObject();if(!IsLocalHost(node))continue;localIds.insert(node["id"].toString());node["project_data_directory"]=folder;nodes[i]=node;}
        fProject["nodes"]=nodes;
        auto groups=fProject["groups"].toArray();
        for(int i=0;i<groups.size();++i){auto group=groups[i].toObject();if(!group["project_mode"].toBool())continue;auto folders=group["project_directories"].toObject();QSet<QString> used{group["ecc"].toObject()["node_id"].toString()};for(const auto &value:group["receivers"].toArray())used.insert(value.toObject()["node_id"].toString());for(const auto &id:localIds)if(used.contains(id))folders[id]=folder;group["project_directories"]=folders;groups[i]=group;}
        fProject["groups"]=groups;SaveProject();fLocalDataRoot->setText(folder);RefreshTables();
        fLog->appendPlainText(tr("Project folder saved: %1. Applies to groups on this computer at their next service start. Running services and existing data are unchanged.").arg(folder));
    }catch(const std::exception &error){fProject=before;fLog->appendPlainText(QString::fromUtf8(error.what()));}
}
void DistributedDeploymentWindow::LocalNode(){try{Require(QDir::isAbsolutePath(fLocalDataRoot->text().trimmed()),"Use an absolute local project folder");SaveProject();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));return;}
    const auto root=fRoot->text(),programs=QCoreApplication::applicationDirPath(),address=fAddress->text();const int port=fPort->value();const auto dataRoot=fLocalDataRoot->text().trimmed();const auto log=Logger();
    Async([=]{log("Starting / checking master configuration service…");const auto master=EnsureMaster(root,programs,address,port);log("Starting / checking the local node agent…");const auto localRoot=PreferredNodeCacheDirectory(QSettings().value(StartupConfigurationKey()+"/slave-cache-directory",DefaultNodeCacheDirectory()).toString());QJsonObject settings{{"bind",address},{"port",24260},{"data_directory",dataRoot}};if(QFile::exists(localRoot+"/node.json"))settings=Parse(Read(localRoot+"/node.json"));auto node=EnsureLocalNode(localRoot,programs,settings["bind"].toString(),settings["port"].toInt(),settings["data_directory"].toString());node=JoinLocalNodeToProject(master,node);node["name"]=tr("This computer");node["project_data_directory"]=dataRoot;return QJsonObject{{"master",master},{"node",node}};},[this](QJsonObject result){fMaster=result["master"].toObject();auto nodes=fProject["nodes"].toArray();const auto node=result["node"].toObject();bool found=false;for(int i=0;i<nodes.size();++i)if(nodes[i].toObject()["id"]==node["id"]){nodes[i]=node;found=true;}if(!found)nodes.append(node);fProject["nodes"]=nodes;fProject["local_project_directory"]=node["project_data_directory"];SaveProject();RefreshTables();fLog->appendPlainText(tr("This computer joined automatically. Add boards, then click Start project services."));});
}
