QString DistributedDeploymentWindow::SelectedGroup()const{const int row=fGroups->currentRow();return row>=0 && fGroups->item(row,0)?fGroups->item(row,0)->data(Qt::UserRole).toString():(fDailyGroups?fDailyGroups->currentData().toString():QString());}
QSet<QString> DistributedDeploymentWindow::SelectedGroups()const{QSet<QString> result;if(fGroups)for(const auto &row:fGroups->selectionModel()->selectedRows())if(fGroups->item(row.row(),0))result.insert(fGroups->item(row.row(),0)->data(Qt::UserRole).toString());if(result.isEmpty() && !SelectedGroup().isEmpty())result.insert(SelectedGroup());return result;}

void DistributedDeploymentWindow::RemoveGroup(){const auto id=SelectedGroup();if(id.isEmpty())return;try{const auto activePath=fRoot->text()+"/active-instances.json";if(QFile::exists(activePath)){const auto active=Parse(Read(activePath));for(auto it=active.begin();it!=active.end();++it)if(it.value().toObject()["group_id"]==id)Require(DeploymentInstanceReleased(it.value().toObject()),"Normally stop this group, or use Review terminated group after inspecting hardware and data");}QJsonArray groups;for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]!=id)groups.append(value);fProject["groups"]=groups;SaveProject();RefreshTables();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::Publish(){try{RefreshSourceFiles();SaveProject();QJsonArray hosts;for(const auto &value:fProject["nodes"].toArray())hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto nodes=fProject["nodes"].toArray();const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const bool accepted=fConfigurationWarningAccepted;const auto log=Logger();Async([=]{const auto master=EnsureMaster(root,programs,address,port);return QJsonObject{{"master",master},{"preparation",PrepareProject(master,nodes,bundle,log,QString(),accepted)}};},[this](QJsonObject result){fMaster=result["master"].toObject();fPreparation=result["preparation"].toObject();RefreshTables();fLog->appendPlainText(tr("All required nodes prepared release %1. You can now start the services." ).arg(fPreparation["release_id"].toString().left(12)));});}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::Activate(){
 try{RefreshSourceFiles();SaveProject();const auto selectedGroups=SelectedGroups();Require(!selectedGroups.isEmpty(),"Select one or more ECC groups to start.");auto ordered=selectedGroups.values();ordered.sort();const auto selected=ordered.first();QString experiment;for(const auto &entry:fProject["groups"].toArray()){const auto group=entry.toObject();if(!selectedGroups.contains(group["id"].toString()))continue;if(experiment.isEmpty())experiment=group["experiment"].toString();Require(group["experiment"].toString()==experiment,"Selected ECC groups must use the same experiment for one unified Run Setup.");}QJsonArray hosts;for(const auto &value:fProject["nodes"].toArray())hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto nodes=fProject["nodes"].toArray();const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const bool accepted=fConfigurationWarningAccepted;const auto log=Logger();
  Async([=]{log("Starting / checking selected project services…");const auto master=EnsureMaster(root,programs,address,port);const auto prepared=PrepareProject(master,nodes,bundle,log,QString(),accepted,selectedGroups);const auto active=ActivateProject(master,nodes,prepared,log,QString(),selectedGroups);return QJsonObject{{"master",master},{"preparation",prepared},{"activation",active}};},[this,selected,selectedGroups](QJsonObject result){fMaster=result["master"].toObject();fPreparation=result["preparation"].toObject();fActivation=result["activation"].toObject();RefreshTables();if(fCloseAfterWait || (fCanceled && fCanceled->load()))return;fSelected=ConsoleConfiguration(fMaster,fPreparation,fActivation,selected,fBase,selectedGroups);fLog->appendPlainText(tr("Selected ECC groups and receivers are ready. Applying this configuration to Run Setup."));accept();});
 }catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}
}
void DistributedDeploymentWindow::Observe(){if(fMaster.isEmpty())return;const auto master=fMaster;const auto nodes=fProject["nodes"].toArray();Async([=]{return ObserveDeployment(master,nodes);},[this](QJsonObject result){auto nodes=fProject["nodes"].toArray();for(const auto &value:result["hosts"].toArray()){const auto observed=value.toObject();for(int i=0;i<nodes.size();++i)if(nodes[i].toObject()["id"]==observed["node_id"]){auto node=nodes[i].toObject();node["observation"]=observed["online"].toBool()?tr("Agent online; see log for instance processes"):tr("Offline: %1").arg(observed["message"].toString());if(observed["online"].toBool())node["inventory"]=observed;nodes[i]=node;}for(const auto &instance:observed["instances"].toArray()){const auto item=instance.toObject();fLog->appendPlainText(QString("%1 / %2: %3, PIDs=%4").arg(observed["name"].toString(),item["instance_id"].toString(),item["actual_state"].toString(item["phase"].toString()),QString::fromUtf8(QJsonDocument(item["actual_pids"].toArray()).toJson(QJsonDocument::Compact))));}}fProject["nodes"]=nodes;for(const auto &value:result["operations"].toArray()){const auto record=value.toObject();fLog->appendPlainText(tr("Saved operation history %1: %2 %3 (not the current service state)").arg(record["request"].toObject()["operation_id"].toString(),record["phase"].toString(),record["observation_error"].toString()));}SaveProject();RefreshTables();});}
void DistributedDeploymentWindow::StopSelected(bool repair){const auto group=SelectedGroup();if(group.isEmpty() || fPreparation.isEmpty()){fLog->appendPlainText(tr("Select a deployed ECC group first."));return;}if(repair && QMessageBox::warning(this,tr("Terminate group"),tr("Terminate only matching backend processes in the selected group? This does not prove boards have stopped, complete a Run or clear UNKNOWN."),QMessageBox::Yes|QMessageBox::No,QMessageBox::No)!=QMessageBox::Yes)return;const auto master=fMaster,prepared=fPreparation;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();Async([=]{return StopGroup(master,nodes,prepared,group,repair,log);},[this](QJsonObject result){fLog->appendPlainText(tr("Selected group result: %1").arg(result["phase"].toString()));});}
void DistributedDeploymentWindow::ReviewTerminatedGroup(){
    const auto group=SelectedGroup();if(fBusy || group.isEmpty() || fMaster.isEmpty())return;
    if(QMessageBox::warning(this,tr("Review terminated group"),tr("Continue only after you have verified that board acquisition is stopped (or the boards have been reset) and existing raw data has been preserved.\n\nThe node will verify that matching backend and receiver processes are absent. This releases only the deployment lock so this group can be edited or removed. It does not mark the old Run complete, clear hardware UNKNOWN, delete data, or start hardware.\n\nHave you verified these conditions?"),QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)return;
    const auto master=fMaster;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();
    Async([=]{return ReleaseTerminatedGroup(master,nodes,group,log);},[this](QJsonObject){RefreshTables();fLog->appendPlainText(tr("Inspection release recorded. You can remove this draft group, or save edits and click Start project services. Old audit and raw data are retained."));});
}
void DistributedDeploymentWindow::UseSelected(){if(fBusy)return;try{const auto groups=SelectedGroups();auto names=groups.values();names.sort();Require(!names.isEmpty(),"Select an ECC group.");fSelected=ConsoleConfiguration(fMaster,fPreparation,fActivation,names.first(),fBase,groups);accept();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}

void DistributedDeploymentWindow::StartAndUse(){Activate();}

void DistributedDeploymentWindow::UpdatePathSummary(){
    if(!fPathSummary)return;
    QJsonObject group;const auto selected=fDailyGroups->currentData().toString();
    for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]==selected)group=value.toObject();
    if(group.isEmpty()){fPathSummary->setText(tr("Select an ECC group to see its configuration and data folders."));return;}
    fPathSummary->setText(DeploymentPathSummary(group,fProject["nodes"].toArray(),fSource->text().trimmed(),fBase.outputDir));
}

void DistributedDeploymentWindow::RefreshSourceFiles(){
 fConfigurationWarningAccepted=false;
 if(fSync->isChecked() && QFile::exists(fRoot->text()+"/active-instances.json")){bool active=false;const auto instances=Parse(Read(fRoot->text()+"/active-instances.json"));for(auto it=instances.begin();it!=instances.end();++it)active=active || it.value().toObject()["phase"]=="active";
 if(active){if(QMessageBox::warning(this,tr("Update project files"),tr("Copy the source configuration to the project folders without forcing ECC to Idle? Files may change while hardware keeps its previously configured parameters. Accepted hardware commands finish before known-busy files are replaced. Unknown state may be accepted; this sends no hardware configuration command."),QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)throw std::runtime_error("Configuration synchronization canceled by operator");fConfigurationWarningAccepted=true;}}
 auto groups=fProject["groups"].toArray();auto files=fFiles;QSet<QString> used;
 for(int i=0;i<groups.size();++i){auto group=groups[i].toObject();if(group["project_mode"].toBool()){
  group["master_repository"]=QFileInfo(fSource->text().trimmed()).absoluteFilePath();group["sync_configuration"]=fSync->isChecked();group["repository_files"]=OriginalRepository(group["master_repository"].toString(),group["id"].toString(),&files);groups[i]=group;
 }for(const auto &value:group["repository_files"].toArray())used.insert(value.toObject()["file"].toString());}
 for(auto it=files.begin();it!=files.end();)if(!used.contains(it.key()))it=files.erase(it);else ++it;
 fFiles=files;fProject["groups"]=groups;
}
void DistributedDeploymentWindow::OpenSyncDialog(){
 if(fBusy)return;
 try{
  RefreshSourceFiles();SaveProject();const auto nodes=fProject["nodes"].toArray();Require(!nodes.isEmpty(),"Add this computer or pair a slave first");
  QDialog dialog(this);dialog.setWindowTitle(tr("Sync project configuration"));QVBoxLayout layout(&dialog);
  auto *source=new QLabel(tr("Source on master: %1\nSelect execution hosts. Slaves receive and automatically apply files to their own project folders; active projects can update files after acknowledgment; this does not configure hardware. Known hardware commands finish before files are replaced.").arg(fSource->text()),&dialog);source->setWordWrap(true);layout.addWidget(source);
  QList<QCheckBox *> choices;for(const auto &value:nodes){const auto node=value.toObject();auto *check=new QCheckBox(node["name"].toString()+" — "+node["url"].toString(),&dialog);check->setProperty("node_id",node["id"].toString());check->setChecked(true);choices.append(check);layout.addWidget(check);}
  QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel,&dialog);buttons.button(QDialogButtonBox::Ok)->setText(tr("Sync selected hosts"));layout.addWidget(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()!=QDialog::Accepted)return;
  QSet<QString> targets;for(auto *choice:choices)if(choice->isChecked())targets.insert(choice->property("node_id").toString());Require(!targets.isEmpty(),"Select at least one execution host");
  QJsonArray hosts;for(const auto &value:nodes)hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const bool accepted=fConfigurationWarningAccepted;const auto log=Logger();
  Async([=]{const auto master=EnsureMaster(root,programs,address,port);return QJsonObject{{"master",master},{"sync",SyncProject(master,nodes,bundle,targets,log,accepted)}};},[this](QJsonObject result){fMaster=result["master"].toObject();fLog->appendPlainText(tr("Configuration delivery finished. Applied / pending results are shown above; no acquisition command was sent."));});
 }catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}
}

void DistributedDeploymentWindow::StopProjectServices(){
 if(fBusy || fMaster.isEmpty())return;const auto master=fMaster,prepared=fPreparation,project=fProject;const auto nodes=project["nodes"].toArray();const auto log=Logger();
 Async([=]{const auto active=Parse(Read(master["root"].toString()+"/active-instances.json"));
  for(auto it=active.begin();it!=active.end();++it){const auto entry=it.value().toObject();if(entry["role"]!="ecc" || entry["phase"]!="active")continue;for(const auto &v:project["groups"].toArray())if(v.toObject()["id"]==entry["group_id"]){const auto ecc=v.toObject()["ecc"].toObject();const int state=OriginalEccState(ecc["address"].toString(),ecc["port"].toInt());Require(state!=5 && state!=6,"Stop the Run in the main window before stopping project services");}}
  QJsonArray receipts;for(const auto &v:project["groups"].toArray()){const auto group=v.toObject();if(active.contains(group["id"].toString()+"-ecc"))receipts.append(StopGroup(master,nodes,prepared,group["id"].toString(),false,log));}return QJsonObject{{"receipts",receipts}};
 },[this](QJsonObject){fLog->appendPlainText(tr("Project services stopped. Configuration, raw files and logs were retained."));});
}
